	i32 splitCount;   /* +0x90: (by use) items a block holds before it splits (setBy's b) */
	i32 depth;   /* +0x94: the blocks' recursion depth (at most 8) */
	i32 lastHit;   /* +0x98: (by use) space_collideAt's last result */
